class SetupsAndTeardowns(object):
    __collecting_interface_traffic_started = False
    __syslog_aic_started = False
    __syslog_remote_host_started = False
    __tcpdump_remote_host_started = False

    def __init__(self):
        try:
            BuiltIn().get_library_instance('ute_wtssim')
            BuiltIn().get_library_instance('ute_fsmaccess')
            self.ute_tshark = BuiltIn().get_library_instance('ute_tshark')
            self.ta5g_syslog_instance = BuiltIn().get_library_instance('ta5g_syslog')
        except RuntimeError:
            logger.warn(
                "Please import ta5g_setups_and_teardowns library by resource 'resources/common/libraries_instances.robot' as the first resource!"
            )
        self.ta5g_iphy_instance = ta5g_iphy()
        self.ta5g_enb_instance = ta5g_enb()
        self.ta5g_egate_instance = ta5g_egate.ta5g_egate()
        self.ta5g_testline_mgmt_instance = ta5g_testline_management()
        self.ta5g_commissioning_instance = ta5g_commissioning()
        self.ta5g_tshark_instance = ta5g_tshark()
        self.ta5g_ue_mobility_instance = ta5g_ue_mobility.ta5g_ue_mobility()

    @staticmethod
    def traffic_collection_on_interface_started():
        return SetupsAndTeardowns.__collecting_interface_traffic_started

    @log_method_name
    def configure_enb_and_iphy_and_reach_onair(
        self,
        lua_cfg_filepath,
        iphy_xml_filepath,
        scfc_filename,
        swconfig_flags_list=[],
        output_dirpath=None,
        yaml_filename=None,
    ):
        """
        This method allows you to:
        - Update enb/gnb and iphy/airphone configuration
        - Perform full commisioning and reach onair status


        :param string lua_cfg_filepath: File path of .lua config file
        :param string iphy_xml_filepath: File path of iphy/airphone config file
        :param string scfc_filename: Name of scfc file (This file should be located in the folder with the name corresponding to the build name)
        :param list swconfig_flags_list: List of R&D flags, which should be added to swconfig file
        :param string output_dirpath: Path to output directory
        :param string yaml_filename: Name of config file needed to test ABIC
        """
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        self.update_iphy_configuration_and_modify_swconfig(
            iphy_xml_filepath=iphy_xml_filepath,
            swconfig_flags_list=swconfig_flags_list,
            output_dirpath=output_dirpath,
            yaml_filename=yaml_filename,
        )

        self.perform_full_commissioning_and_reach_onair(
            lua_cfg_filepath=lua_cfg_filepath,
            scfc_filename=scfc_filename,
            output_dirpath=output_dirpath,
            yaml_filename=yaml_filename,
        )
        self.ta5g_iphy_instance.reset_wts_and_wait_for_enb_to_reach_configured_state()

    @log_method_name
    def setup_test_line(self, iphy_xml_filepath, scfc_filename, perform_full_commissioning=True,
                        perform_testline_reset=False, skipped_branch=None, output_dirpath=None):
        self.start_default_logging(output_dirpath=output_dirpath)
        try:
            if perform_full_commissioning:
                self.update_airphone_configuration_and_perform_full_commissioning(iphy_xml_filepath=iphy_xml_filepath,
                                                                             scfc_filename=scfc_filename,
                                                                             skipped_branch=skipped_branch,
                                                                             output_dirpath=output_dirpath)
            if perform_testline_reset:
                ta5g_testline_management().reset_testline()
                ta5g_iphy().check_radios_availability()
        finally:
            self.stop_default_logging(output_dirpath=output_dirpath)

    @log_method_name
    def setup_test_line_aic(self, iphy_xml_filepath=None, scfc_filename_cu=None, scfc_filename_du1=None, scfc_filename_du2=None,
                            scfc_filepath_cu=None, scfc_filepath_du1=None, scfc_filepath_du2=None,
                            output_dirpath=None, perform_testline_reset=True, perform_full_commissioning=True):
        """
        This method allows you to setup testline in aic:
        - perform full commisioning in vcu and vdu (1 or 2 or both)
        - update and put custom iphy xml

        scfc_filename_cu, scfc_filename_du1, scfc_filename_du2 or scfc_filepath_cu, scfc_filepath_du1, scfc_filepath_du2 parameters should be used
        depending on whether you use the scfc file name or the scfc file path:

        - If scfc will be located in default folder or in the folder with the name corresponding to the release name, please specify only the name od scfc
          and use parameters:
          scfc_filename_cu, scfc_filename_du1, scfc_filename_du2

        - If you want to use scfc path instead of way described above, please use parameters:
          scfc_filepath_cu, scfc_filepath_du1, scfc_filepath_du2


         :param string iphy_xml_filepath: File path of iphy/airphone config file
         :param string scfc_filename_cu: Name of scfc file for vcu, default None
         :param string scfc_filename_du1: Name of scfc file for vdu1, default None
         :param string scfc_filename_du2: Name of scfc file for vdu2, default None
         :param scfc_filepath_cu: scfc filepath for vcu
         :param scfc_filepath_du1: scfc filepath for vdu1
         :param scfc_filepath_du2: scfc filepath for vdu2
         :param output_dirpath:
         :param perform_testline_reset:
         :param perform_full_commissioning:
        """
        number_of_vdu = ta5g_admin_operations().get_number_of_vdu()

        try:
            if perform_full_commissioning:
                ta5g_iphy().update_and_put_iphy_xml_aic(input_filepath=iphy_xml_filepath, output_dirpath=output_dirpath)
                if scfc_filepath_cu and scfc_filepath_du1:
                    ta5g_commissioning().send_commissioning_vcu_and_all_vdus_scfc_filepath(scf_vcu_filepath=scfc_filepath_cu,
                                                                                           scf_vdu_1_filepath=scfc_filepath_du1,
                                                                                           scf_vdu_2_filepath=scfc_filepath_du2)
                else:
                    ta5g_commissioning().send_commissioning_vcu_and_all_vdus(scf_vcu=scfc_filename_cu, scf_vdu_1=scfc_filename_du1, scf_vdu_2=scfc_filename_du2)
            if perform_testline_reset:
                for vdus in range(number_of_vdu):
                    ta5g_testline_management().trigger_site_reset_aic_vdu(vdu=vdus+1)
                ta5g_testline_management().trigger_site_reset_aic_vcu()
            ta5g_iphy().wait_for_all_radios_to_be_enabled_aic(number_of_vdu=number_of_vdu, timeout=180)
            ta5g_admin_operations().wait_for_f1_links_to_be_available_aic()
        finally:
            self.stop_default_logging_aic(output_dirpath=output_dirpath)

    @log_method_name
    def update_airphone_configuration_and_perform_full_commissioning(self, iphy_xml_filepath, scfc_filename,
                                                                     skipped_branch=None,
                                                                     output_dirpath=None):
        release_name = self.ta5g_enb_instance.get_enb_active_release_name()
        if not release_name == skipped_branch:
            self.update_iphy_configuration_and_modify_swconfig(
                iphy_xml_filepath=iphy_xml_filepath,
                output_dirpath=output_dirpath
            )
            ta5g_commissioning().find_scfc_and_fix_and_send_full_commissioning(
                scfc_filename=scfc_filename, output_dirpath=output_dirpath
            )
            ta5g_testline_management().reset_testline()
            ta5g_iphy().check_radios_availability()

    @log_method_name
    def setup_default_configuration(
        self,
        lua_cfg_filepath,
        iphy_xml_filepath,
        scfc_filename,
        swconfig_flags_list=[],
        output_dirpath=None,
        yaml_filename=None,
    ):
        """
        This method allows you to perform a basic configuration, it consists of:

         - Update enb/gnb and iphy/airphone configuration

         - Start simenb/simgnb interface

         - Start default logging

         - Perform full commissioning and reach onair status


         :param string lua_cfg_filepath: File path of .lua config file
         :param string iphy_xml_filepath: File path of iphy/airphone config file
         :param string scfc_filename: Name of scfc file (This file should be located in the folder with the name corresponding to the build name)
         :param list swconfig_flags_list: List of R&D flags, which should be added to swconfig file
         :param string output_dirpath: Path to output directory
         :param string yaml_filename: Name of config file needed to test ABIC
        """
        yaml_filename = self.ta5g_commissioning_instance.make_new_yaml_if_overloaded_pipe(
            scfc_filename=scfc_filename, yaml_filename=yaml_filename
        )
        self.update_iphy_configuration_and_modify_swconfig_and_start_simenb_interface(
            iphy_xml_filepath=iphy_xml_filepath,
            swconfig_flags_list=swconfig_flags_list,
            output_dirpath=output_dirpath,
            yaml_filename=yaml_filename,
        )
        self.ta5g_iphy_instance.reset_wts_and_wait_for_enb_to_reach_configured_state(output_dirpath=output_dirpath)
        self.start_default_logging_and_perform_full_commissioning_and_reach_onair(
            lua_cfg_filepath=lua_cfg_filepath,
            scfc_filename=scfc_filename,
            output_dirpath=output_dirpath,
            yaml_filename=yaml_filename,
        )

    @log_method_name
    def update_enb_and_iphy_configuration_and_perform_full_commissioning(
        self, iphy_xml_filepath, scfc_filename, swconfig_flags_list=[], output_dirpath=None, yaml_filename=None,
        bts_id="1"
    ):
        """
        This method allows you to:
        - Update enb/gnb and iphy/airphone configuration
        - Start default logging


        :param string iphy_xml_filepath: File path of iphy/airphone config file
        :param string scfc_filename: Name of scfc file (This file should be located in the folder with the name corresponding to the build name)
        :param list swconfig_flags_list: List of R&D flags, which should be added to swconfig file
        :param string output_dirpath: Path to output directory
        :param string yaml_filename: Name of config file needed to test ABIC
        """
        self.update_iphy_configuration_and_modify_swconfig(
            iphy_xml_filepath=iphy_xml_filepath,
            swconfig_flags_list=swconfig_flags_list,
            output_dirpath=output_dirpath,
            yaml_filename=yaml_filename,
        )
        self.ta5g_iphy_instance.reset_wts_and_wait_for_enb_to_reach_configured_state()
        self.start_default_logging(output_dirpath=output_dirpath)
        try:
            self.ta5g_commissioning_instance.find_scfc_and_fix_and_send_full_commissioning(
                scfc_filename=scfc_filename, output_dirpath=output_dirpath, bts_id=bts_id
            )
            self.ta5g_iphy_instance.reset_wts_and_wait_for_enb_to_reach_configured_state()
        finally:
            self.stop_default_logging(output_dirpath)

    @log_method_name
    def start_default_logging_and_perform_full_commissioning_and_reach_onair(
        self, lua_cfg_filepath, scfc_filename, remote_host=None, output_dirpath=None, yaml_filename=None
    ):
        """
        This method allows you to:
        - Start default logging
        - Perform full commissioning and reach onair status


        :param string lua_cfg_filepath: File path of .lua config file
        :param string scfc_filename: Name of scfc file (This file should be located in the folder with the name corresponding to the build name)
        :param string remote_host: Ip adress of remote host
        :param string output_dirpath: Path to output directory
        :param string yaml_filename: Name of config file needed to test ABIC
        """
        self.start_default_logging(remote_host=remote_host, output_dirpath=output_dirpath)
        self.perform_full_commissioning_and_reach_onair_without_default_logging(
            lua_cfg_filepath=lua_cfg_filepath,
            scfc_filename=scfc_filename,
            remote_host=remote_host,
            output_dirpath=output_dirpath,
            yaml_filename=yaml_filename,
        )

    @log_method_name
    def update_iphy_configuration_and_modify_swconfig(
        self,
        iphy_xml_filepath,
        swconfig_flags_list=[],
        remote_host=None,
        iphy_lmp_ip=IPHY0_LMP_IP,
        output_dirpath=None,
        yaml_filename=None,
    ):
        """
        This method allows you to:
        - Modify swconfig file
        - Update iphy/airphone configuration


        :param string iphy_xml_filepath: File path of iphy/airphone config file
        :param list swconfig_flags_list: List of R&D flags, which should be added to swconfig file
        :param string remote_host: Ip adress of remote host
        :param string iphy_lmp_ip: Iphy/airphone LMP IP adress
        :param string output_dirpath: Path to output directory
        :param string yaml_filename: Name of config file needed to test ABIC
        """
        self.ta5g_enb_instance.backup_and_modify_swconfig_file(
            parameters_list=swconfig_flags_list, output_dirpath=output_dirpath, remote_host=remote_host
        )
        self.update_and_put_iphy_xml_wrapper(iphy_xml_filepath, output_dirpath, remote_host, iphy_lmp_ip, yaml_filename)

    @log_method_name
    def update_iphy_configuration_and_modify_swconfig_and_start_simenb_interface(
        self,
        iphy_xml_filepath,
        swconfig_flags_list=[],
        remote_host=None,
        iphy_lmp_ip=IPHY0_LMP_IP,
        output_dirpath=None,
        yaml_filename=None,
    ):
        """
        This method allows you to:
        - Start simenb/simgnb interface
        - Modify swconfig file
        - Update iphy/airphone configuration


        :param string iphy_xml_filepath: File path of iphy/airphone config file
        :param list swconfig_flags_list: List of R&D flags, which should be added to swconfig file
        :param string remote_host: Ip adress of remote host
        :param string iphy_lmp_ip: Iphy/airphone LMP IP adress
        :param string output_dirpath: Path to output directory
        :param string yaml_filename: Name of config file needed to test ABIC
        """
        self.ta5g_testline_mgmt_instance.start_default_simulated_enb_interface()
        self.ta5g_enb_instance.backup_and_modify_swconfig_file(
            parameters_list=swconfig_flags_list, output_dirpath=output_dirpath, remote_host=remote_host
        )
        self.update_and_put_iphy_xml_wrapper(iphy_xml_filepath, output_dirpath, remote_host, iphy_lmp_ip, yaml_filename)

    @log_method_name
    def modify_vendor_file_and_update_enb_and_iphy_configuration_and_reach_onair(
        self,
        vendor_parameters,
        lua_cfg_filepath,
        iphy_xml_filepath,
        scfc_filename,
        swconfig_flags_list=[],
        output_dirpath=None,
        yaml_filename=None,
    ):
        """
        This method allows you to:
        - Update iphy/airphone and gnb/enb configuration and start simenb/simgnb interface
        - Start default logging
        - Modify vendor file and perform commissioning
        - Reach onair status


        :param list vendor_parameters: list of vendor parameters
        :param string lua_cfg_filepath: File path of .lua config file
        :param string iphy_xml_filepath: File path of iphy/airphone config file
        :param string scfc_filename: Name of scfc file (This file should be located in the folder with the name corresponding to the build name)
        :param list swconfig_flags_list: List of R&D flags, which should be added to swconfig file
        :param string output_dirpath: Path to output directory
        :param string yaml_filename: Name of config file needed to test ABIC
        """
        self.update_iphy_configuration_and_modify_swconfig_and_start_simenb_interface(
            iphy_xml_filepath=iphy_xml_filepath,
            swconfig_flags_list=swconfig_flags_list,
            output_dirpath=output_dirpath,
            yaml_filename=yaml_filename,
        )
        self.ta5g_iphy_instance.reset_wts_and_wait_for_enb_to_reach_configured_state()
        self.start_default_logging(output_dirpath=output_dirpath)
        self.ta5g_commissioning_instance.modify_vendor_file_and_do_commissioning(
            vendor_parameters=vendor_parameters,
            scfc_filename=scfc_filename,
            output_dirpath=output_dirpath,
            yaml_filename=yaml_filename,
        )
        self.ta5g_egate_instance.reach_onair(lua_cfg=lua_cfg_filepath)

    @log_method_name
    def perform_full_commissioning_and_reach_onair(
        self, lua_cfg_filepath, scfc_filename, remote_host=None, output_dirpath=None, yaml_filename=None,
        bts_id="1"
    ):
        """
        This method allows you to:
        - Start default logging
        - Perform full commisioning
        - Reach onair status


        :param string lua_cfg_filepath: File path of .lua config file
        :param string scfc_filename: Name of scfc file (This file should be located in the folder with the name corresponding to the build name)
        :param string remote_host: Ip adress of remote host
        :param string output_dirpath: Path to output directory
        :param string yaml_filename: Name of config file needed to test ABIC
        :param string bts_id: Id of bts to perform commissioning
        """
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        self.start_default_logging(remote_host=remote_host, output_dirpath=output_dirpath)
        try:
            self.ta5g_commissioning_instance.find_scfc_and_fix_and_send_full_commissioning(
                scfc_filename=scfc_filename,
                output_dirpath=output_dirpath,
                remote_host=remote_host,
                yaml_filename=yaml_filename,
                bts_id=bts_id
            )
            self.ta5g_egate_instance.reach_onair(lua_cfg=lua_cfg_filepath, logs_dirpath=output_dirpath)
        finally:
            self.stop_default_logging(output_dirpath=output_dirpath)

    @log_method_name
    def perform_full_commissioning_and_reach_onair_without_default_logging(
        self, lua_cfg_filepath, scfc_filename, remote_host=None, output_dirpath=None, yaml_filename=None, bts_id="1"
    ):
        """
        This method allows you to:
        - Perform full commissioning
        - Reach onair status


        :param string lua_cfg_filepath: File path of .lua config file
        :param string scfc_filename: Name of scfc file (This file should be located in the folder with the name corresponding to the build name)
        :param string remote_host: Ip adress of remote host
        :param string output_dirpath: Path to output directory
        :param string yaml_filename: Name of config file needed to test ABIC
        :param string bts_id: Id of bts to perform commissioning
        """
        self.ta5g_commissioning_instance.find_scfc_and_fix_and_send_full_commissioning(
            scfc_filename=scfc_filename,
            remote_host=remote_host,
            output_dirpath=output_dirpath,
            yaml_filename=yaml_filename,
            bts_id=bts_id
        )
        # self.ta5g_iphy_instance.check_radios_availability(alias='check_for_rmods_after_full_commissioning')
        self.ta5g_iphy_instance.reset_wts_and_wait_for_enb_to_reach_configured_state()
        self.ta5g_egate_instance.reach_onair(lua_cfg=lua_cfg_filepath, logs_dirpath=output_dirpath)

    def update_and_put_iphy_xml_wrapper(self, input_filepath, output_dirpath, remote_host, iphy_lmp_ip, yaml_filename):
        self._backup_and_modify_l2ps_node_in_iphy_xml(input_filepath)
        self.ta5g_iphy_instance.update_and_put_iphy_xml(
            input_filepath=input_filepath,
            output_dirpath=output_dirpath,
            remote_host=remote_host,
            iphy_lmp_ip=iphy_lmp_ip,
            yaml_filename=yaml_filename,
        )
        self._clear_backup_iphy_xml(input_filepath)

    def _backup_and_modify_l2ps_node_in_iphy_xml(self, input_filepath):
        if self.ta5g_enb_instance.get_smod_position_on_given_fsmr4_enb() == 'RightSide':
            self._change_l2ps_node_id(input_filepath)

    def _change_l2ps_node_id(self, input_filepath):
        for line in fileinput.input(input_filepath, inplace=1, backup='.bak'):
            line = re.sub(r'<l2PsNodeId>\d+</l2PsNodeId>', r'<l2PsNodeId>8778</l2PsNodeId>', line.rstrip())
            print(line)

    def _clear_backup_iphy_xml(self, input_filepath):
        back_filepath = input_filepath + '.bak'
        os.system('mv {} {}'.format(back_filepath, input_filepath))

    @log_method_name
    def start_default_logging(
        self, remote_host=None, output_dirpath=None, tcpdump_prefix='gnb_F1_E1_RRC', alias="default_tcpdump_alias"
    ):
        if ta5g_admin_operations().is_classical():
            self.start_default_logging_classical(remote_host, output_dirpath, tcpdump_prefix, alias)
        else:
            self.start_default_logging_aic(remote_host, output_dirpath, tcpdump_prefix, alias)

    @log_method_name
    def start_default_logging_classical(
        self, remote_host=None, output_dirpath=None, tcpdump_prefix='gnb_F1_E1_RRC', alias="default_tcpdump_alias"
    ):
        """
        This method allows you to:
        - Start syslog for enb/gnb and iphy/airphone
        - Start tshark on s1 and uu interfaces
        - Start tshark on enb/gnb lmp interfaces
        - Start tcpdump on remote interface
        - Start additional logs collection like CPLANE logs and L1L2 logs


        :param string remote_host: Ip adress of remote host
        :param string output_dirpath: Path to output directory
        :param string tcpdump_prefix: Tcpdump prefix
        :param string alias: Alias for tshark
        """
        os.system("ssh-keygen -f '/home/ute/.ssh/known_hosts' -R '127.0.0.1'")
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        collect_cplane_logs = BuiltIn().get_variable_value('${COLLECT_CPLANE_LOGS}')
        collect_lmp_pcap = BuiltIn().get_variable_value('${COLLECT_LMP_PCAP}')

        if collect_cplane_logs:
            self.ta5g_enb_instance.create_cp_runtime_file(alias='cp_runtime')
            self.ta5g_testline_mgmt_instance.trigger_site_reset()
            self.ta5g_iphy_instance.check_radios_availability()
        self.ta5g_syslog_instance.start_default_syslog_for_enb_and_iphy(
            path.join(output_dirpath, ENB_SUBDIR), None
        )
        self.ta5g_tshark_instance.start_default_tshark_on_s1_mme_and_uu_interfaces(
            path.join(output_dirpath, TSHARK_SUBDIR)
        )
        if collect_lmp_pcap:
            self.ta5g_tshark_instance.start_default_tshark_on_enb_lmp_interface(
                path.join(output_dirpath, TSHARK_SUBDIR)
            )

        collect_dcap = BuiltIn().get_variable_value('${COLLECT_DCAP}')
        if collect_dcap:
            ta5g_dcap().start_dcap()

        self.ta5g_tshark_instance.start_tcpdump_on_remote_interface(
            log_filename_prefix=tcpdump_prefix, log_dirpath=path.join(output_dirpath, TSHARK_SUBDIR), alias=alias
        )
        self.ta5g_tshark_instance.start_collecting_L3_on_AP_remote_interface(
            log_filename_prefix='AP_L3', log_dirpath=path.join(output_dirpath, TSHARK_SUBDIR), alias='AP_L3_alias'
        )
        self.ta5g_tshark_instance.start_default_tshark_on_loopback_interface(path.join(output_dirpath, TSHARK_SUBDIR))
        SetupsAndTeardowns.__collecting_interface_traffic_started = True
        if remote_host:
            logs_path_syslog= path.join(output_dirpath, 'remote_host')
            logs_path_tshark= path.join(output_dirpath, TSHARK_SUBDIR)
            self.ta5g_tshark_instance.start_tcpdump_on_remote_interface(log_dirpath=logs_path_tshark, alias='default_tcpdump_alias_remote_host',
                                                                        remote_host=remote_host)
            SetupsAndTeardowns.__tcpdump_remote_host_started = True
            self.ta5g_syslog_instance.start_syslog_for_remote_host(logs_dirpath=logs_path_syslog, remote_hosts=remote_host)
            SetupsAndTeardowns.__syslog_remote_host_started = True
