    @log_method_name
    def stop_default_logging(
        self, output_dirpath=None, remote_host_list=None, check_errors_or_warnings=False, check_faults=False
    ):
        if ta5g_admin_operations().is_classical():
            self.stop_default_logging_classical(output_dirpath, remote_host_list, check_errors_or_warnings, check_faults)
        else:
            self.stop_default_logging_aic(output_dirpath, remote_host_list)

    @log_method_name
    def stop_default_logging_classical(self, output_dirpath=None, remote_host_list=None, check_errors_or_warnings=False, check_faults=False):
        """
        This method allows you to:
        - Stop syslog for enb/gnb and iphy/airphone
        - Stop tshark


        :param string output_dirpath: Path to output directory
        :param list remote_host_list: List of remote host's IP adresses
        :param check_errors_or_warnings: 'both' -> collecting WRN and ERR prints in enb/ERRORS_WARNINGS.txt,
        'err' -> collecting only ERR prints in enb/ERRORS_WARNINGS.txt, 'wrn'  -> collecting only WRN prints in enb/ERRORS_WARNINGS.txt,
        False -> not collecting any warning and errors prints
        """
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        teardown_executor.execute_teardown_methods(
            [
                (self.ta5g_syslog_instance.stop_default_syslog_for_enb_and_iphy, {"remote_hosts": remote_host_list}),
                self.ute_tshark.teardown_all_aliases_for_tshark,
                self.ta5g_tshark_instance.stop_tcpdump_on_remote_interface,
            ]
        )
        SetupsAndTeardowns.__collecting_interface_traffic_started = False
        if SetupsAndTeardowns.__tcpdump_remote_host_started:
            self.ta5g_tshark_instance.stop_tcpdump_on_remote_host()
            SetupsAndTeardowns.__tcpdump_remote_host_started=False
        collect_dcap = BuiltIn().get_variable_value('${COLLECT_DCAP}')
        if collect_dcap:
            ta5g_dcap().stop_and_revert_dcap()
        if check_errors_or_warnings:
            self.ta5g_syslog_instance.check_err_or_wrn_in_gnb_syslog(output_dirpath, check_errors_or_warnings)
        if check_faults:
            self.ta5g_syslog_instance.check_faults_in_gnb_syslog(output_dirpath)
        if SetupsAndTeardowns.__syslog_remote_host_started:
           self.ta5g_syslog_instance.teardown_all_syslog_aliases()
           SetupsAndTeardowns.__syslog_remote_host_started=False

    @log_method_name
    def stop_default_processes_and_gather_logs(self, output_dirpath=None, teardown_egate_instances=True, additional_logs=True):
        """
        This method allows you to:
        - Stop default logging
        - Stop egate and collect egate logs

        :param string output_dirpath: Path to output directory
        :param teardown_egate_instances: Indication if wts instalnces should be closed and their logs collected
        :additional_logs: Indication if additional debug logs should be collected, by default True
        """
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        self.collect_libs_versions(output_dirpath=output_dirpath)
        self.collect_software_versions(output_dirpath=output_dirpath)
        teardown_methods_to_execute = []
        if additional_logs:
            teardown_methods_to_execute.append((self.stop_default_logging_and_collect_debug_files, {"output_dirpath": output_dirpath}))
        if teardown_egate_instances:
            teardown_methods_to_execute.extend([(self.ta5g_egate_instance.teardown_egate_and_collect_logs, {"logs_dirpath": output_dirpath + '/wts'}),
                                                 self.ta5g_egate_instance.copy_egate_console_log_to_output_dir,])
        teardown_executor.execute_teardown_methods(teardown_methods_to_execute)

