    @log_method_name
    def collect_additional_debug_files(self, output_dirpath=None, remote_host=None, iphy_lmp_ip=IPHY0_LMP_IP):
        """
        This method allows you to:
        - Collect debug files for gnb/enb (targetbd, filedirectory, swconfig, hwf, siteconf, raw alarm history and scfc files)
        - Collect debug files for iphy/airphone (config, startup, targetbd files)
        - Collect snapshot for enb/gnb and iphy/airphone
        - Collect TRSExtendedLogs


        :param string output_dirpath: Path to output directory
        :param string remote_host: Ip adress of remote host
        :param string iphy_lmp_ip: Iphy/airphone LMP IP adress
        """
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir() + '/additional_debug_files/'
        logger.console("Collecting additional debug files")
        OperatingSystem().log_environment_variables()
        collect_l1l2 = BuiltIn().get_variable_value('${COLLECT_L1L2_LOGS}')

        teardown_executor.execute_teardown_methods(
            [
                (
                    self.ta5g_enb_instance.get_targetbd_file,
                    {"output_filepath": output_dirpath + '/targetbd_enb.xml', "remote_host": remote_host},
                ),
                (
                    self.ta5g_enb_instance.get_filedirectory_file,
                    {"output_filepath": output_dirpath + '/filedirectory.xml', "remote_host": remote_host},
                ),
                (
                    self.ta5g_enb_instance.get_swconfig_file,
                    {"output_filepath": output_dirpath + '/swconfig.txt', "remote_host": remote_host},
                ),
                # (self.ta5g_enb_instance.get_vendor_file, {"output_filepath": output_dirpath + '/vendor.xml',
                #                                         "remote_host": remote_host}),
                (
                    self.ta5g_enb_instance.get_raw_alarm_history_file,
                    {"output_dirpath": output_dirpath, "remote_host": remote_host},
                ),
                (
                    self.ta5g_iphy_instance.get_iphy_xml_file,
                    {
                        "output_filepath": output_dirpath + '/' + 'iphy.xml',
                        "remote_host": remote_host,
                        "iphy_lmp_ip": iphy_lmp_ip,
                    },
                ),
                (
                    self.ta5g_iphy_instance.get_iphy_startup_file,
                    {
                        "output_filepath": output_dirpath + '/' + 'startup_default.log.txt_or_xz',
                        "remote_host": remote_host,
                        "iphy_lmp_ip": iphy_lmp_ip,
                    },
                ),
                (
                    self.ta5g_iphy_instance.get_iphy_targetbd_file,
                    {
                        "output_filepath": output_dirpath + '/' + 'targetbd_iphy.xml',
                        "remote_host": remote_host,
                        "iphy_lmp_ip": iphy_lmp_ip,
                    },
                ),
                (
                    OperatingSystem().copy_file,
                    {"source": ta5g_interface_tools().get_robot_suite_source(), "destination": output_dirpath},
                ),
                (
                    self.ta5g_enb_instance.get_bts_snapshot,
                    {
                        "output_filepath": output_dirpath
                        + '/{}_{}.zip'.format('bts_snapshot', datetime.datetime.now().strftime("%Y_%m_%dT%H_%M_%S_%f")),
                        "remote_host": remote_host,
                    },
                ),
                (
                    self.ta5g_enb_instance.get_scfc_file,
                    {"output_filepath": output_dirpath + '/backup.xml'},
                ),
                (
                    self.ta5g_iphy_instance.get_iphy_snapshot,
                    {
                        "output_filepath": output_dirpath + '/' + 'iphy_snapshot.zip',
                        "remote_host": remote_host,
                        "iphy_ip": iphy_lmp_ip,
                    },
                )
            ]

        )
        if not collect_l1l2:
            teardown_executor.execute_teardown_methods(
                [(self.collect_sos_report, {"output_dirpath": output_dirpath})]
            )

        release = self.ta5g_enb_instance.get_enb_active_release_name()

        if release.startswith(('SBTS', '5G', 'FL19')):
            self.ta5g_enb_instance.get_extended_trs(output_filepath=output_dirpath + '/TRSExtendedLogs.tar.xz')

    @log_method_name
    def collect_selected_debug_files(self, output_dirpath=None, remote_host=None, iphy_lmp_ip=IPHY0_LMP_IP, selected_collectors=None, omit_collectors=None):
        """
        This method allows you to:
        - Collect debug files for gnb/enb (targetbd, filedirectory, swconfig, hwf, siteconf, raw alarm history and scfc files)
        - Collect debug files for iphy/airphone (config, startup, targetbd files)
        - Collect snapshot for enb/gnb and iphy/airphone
        - Collect TRSExtendedLogs
        - Select which logs to collect and which to omit
        - When providing multiple collectors to collect or to omit, collectors should be provided in a List

        :param string output_dirpath: Path to output directory
        :param string remote_host: Ip adress of remote host
        :param string iphy_lmp_ip: Iphy/airphone LMP IP adress
        :param selected_collectors: Collectors to capture, default value: None, more than one collector should be a List,
                                    if set to None then every collector will be captured
        :param omit_collectors: Collectors to omit, default value: None, more than one collector to omit should be a List
        """
        test_status = BuiltIn().get_variable_value('${TEST STATUS}', default='PASS')
        if test_status == 'FAIL':
            BuiltIn().run_keyword_if_test_failed('Collect Additional Debug Files', output_dirpath)
            return

        log_collectors = {
            "targetbd_file": (
                self.ta5g_enb_instance.get_targetbd_file,
                {"output_filepath": output_dirpath + '/targetbd_enb.xml', "remote_host": remote_host},
            ),
            "filedirectory_file": (
                self.ta5g_enb_instance.get_filedirectory_file,
                {"output_filepath": output_dirpath + '/filedirectory.xml', "remote_host": remote_host},
            ),
            "swconfig_file": (
                self.ta5g_enb_instance.get_swconfig_file,
                {"output_filepath": output_dirpath + '/swconfig.txt', "remote_host": remote_host},
            ),
            "raw_alarm_history_file": (
                self.ta5g_enb_instance.get_raw_alarm_history_file,
                {"output_dirpath": output_dirpath, "remote_host": remote_host},
            ),
            "iphy_xml_file": (
                self.ta5g_iphy_instance.get_iphy_xml_file,
                {
                    "output_filepath": output_dirpath + '/' + 'iphy.xml',
                    "remote_host": remote_host,
                    "iphy_lmp_ip": iphy_lmp_ip,
                },
            ),
            "iphy_startup_file": (
                self.ta5g_iphy_instance.get_iphy_startup_file,
                {
                    "output_filepath": output_dirpath + '/' + 'startup_default.log.txt_or_xz',
                    "remote_host": remote_host,
                    "iphy_lmp_ip": iphy_lmp_ip,
                },
            ),
            "iphy_targetbd_file": (
                self.ta5g_iphy_instance.get_iphy_targetbd_file,
                {
                    "output_filepath": output_dirpath + '/' + 'targetbd_iphy.xml',
                    "remote_host": remote_host,
                    "iphy_lmp_ip": iphy_lmp_ip,
                },
            ),
            "copy_file": (
                OperatingSystem().copy_file,
                {"source": ta5g_interface_tools().get_robot_suite_source(), "destination": output_dirpath},
            ),
            "bts_snapshot": (
                self.ta5g_enb_instance.get_bts_snapshot,
                {
                    "output_filepath": output_dirpath
                    + f'/bts_snapshot_{datetime.datetime.now().strftime("%Y_%m_%dT%H_%M_%S_%f")}.zip',
                    "remote_host": remote_host,
                },
            ),
            "scfc_file": (
                self.ta5g_enb_instance.get_scfc_file,
                {"output_filepath": output_dirpath + '/backup.xml'},
            ),
            "iphy_snapshot": (
                self.ta5g_iphy_instance.get_iphy_snapshot,
                {
                    "output_filepath": output_dirpath + '/' + 'iphy_snapshot.zip',
                    "remote_host": remote_host,
                    "iphy_ip": iphy_lmp_ip,
                },
            ),
            "sos_report": (
                self.collect_sos_report,
                {"output_dirpath": output_dirpath},
            ),
        }
        if selected_collectors is None:
            selected_collectors = list(log_collectors.keys())
        if omit_collectors:
            selected_collectors = [key for key in selected_collectors if key not in omit_collectors]
        methods_to_execute = [log_collectors[key] for key in selected_collectors if key in log_collectors]
        teardown_executor.execute_teardown_methods(methods_to_execute)

