    def collect_sos_report(self, output_dirpath=None):
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir() + '/'
        logger.console("Start collection of SosReport")
        try:
            os.chmod('/opt/iphy/latest/sosReport_ASIL/sosReport_ASIL.sh', 0o755)
            p = subprocess.Popen(
                ['./sosReport_ASIL.sh', '-nr', '-c', '-s'],
                cwd='/opt/iphy/latest/sosReport_ASIL/',
                close_fds=True,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
        )
            p.communicate()
            subprocess.Popen('mv /opt/iphy/latest/sosReport_ASIL/SosReport*.tgz {}'.format(output_dirpath), shell=True)
        except Exception as exc:
            logger.info("Following error occured during collecting sosReport:\n{}".format(exc))
            raise exc

    def run_script_startTest_ASIL(self, timeout=300):
        logger.console("Start running script startTest_ASIL")
        os.chmod('/opt/iphy/latest/sosReport_ASIL/startTest_ASIL.sh', 0o755)
        process = subprocess.Popen(
            ['bash', '-c', "/opt/iphy/latest/sosReport_ASIL/startTest_ASIL.sh"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            universal_newlines=True
        )
        start_time = time.time()
        while time.time() - start_time < timeout:
            output = process.stdout.readline().strip()
            logger.console(output)
            if 'Done. You can now start your tests in egate' in output:
                print(f"Found expected pattern: {output}")
                return True
            elif output:
                print(f"Output: {output}")
        process.wait()
        return False

    def run_script_stopTest_ASIL(self, output_dirpath=None, timeout=600):
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir() + '/'
        logger.console("Start running script stopTest_ASIL")
        os.chmod('/opt/iphy/latest/sosReport_ASIL/stopTest_ASIL.sh', 0o755)
        process = subprocess.Popen(
            ['bash', '-c', "/opt/iphy/latest/sosReport_ASIL/stopTest_ASIL.sh"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            universal_newlines=True
        )
        start_time = time.time()
        while time.time() - start_time < timeout:
            output = process.stdout.readline().strip()
            logger.console(output)
            if re.search(r"SosReport.*\.tgz created", output):
                print(f"Found expected pattern: {output}")
                execution_path = os.getcwd()
                subprocess.Popen('mv {}/SosReport*.tgz {}'.format(execution_path, output_dirpath), shell=True)
                return True
            elif output:
                print(f"Output: {output}")
        process.wait()
        return False

