    def collect_snapshot_from_vcu_aic(self, output_dirpath=None):
        """
        This method allows you to collect snapshot from vcu aic
        :param string output_dirpath: Path to output directory
        """
        logger.console("Collecting snapshot from vCU")
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        directory= 'vcu_snapshot'
        output_dirpath = os.path.join(output_dirpath, directory)
        os.mkdir(output_dirpath)
        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            try:
                snapshot_status = vcu_connection.check_snapshot_status()
                if snapshot_status =='idle':
                    vcu_connection.get_local_snapshot(directory=output_dirpath)
                elif snapshot_status == 'local-ongoing':
                    snapshot_operation_info = vcu_connection.get_snapshot_operations_information()
                    operation_id = snapshot_operation_info[0]['operation_id']
                    vcu_connection.get_local_snapshot_by_id(directory=output_dirpath, operation_id=operation_id)
                else:
                    snapshot_operation_info = vcu_connection.get_snapshot_operations_information()
                    operation_id = snapshot_operation_info[0]['operation_id']
                    vcu_connection.cancel_snapshot_operation(operation_id=operation_id)
                    vcu_connection.get_local_snapshot(directory=output_dirpath)
            except Exception as ex:
                logger.console("Exception: {}".format(ex))
                snapshot_status = vcu_connection.check_snapshot_status()
                logger.console("Snapshot status is {}".format(snapshot_status))
                raise ex

    def collect_snapshot_from_vdu_aic(self, output_dirpath=None):
        """
        This method allows you to collect snapshot for every vdu aic
        :param string output_dirpath: Path to output directory
        """
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        directory= 'vdu_snapshot'
        output_dirpath = os.path.join(output_dirpath, directory)
        os.mkdir(output_dirpath)
        number_of_vdu = ta5g_admin_operations().get_number_of_vdu()
        for vdus in range(number_of_vdu):
            host = ta5g_iphy().get_vdu_master_ip(vdu=vdus)
            logger.console("Collecting snapshot from vDU with IP: {}".format(host))
            vdu = 'vdu_' + str(vdus+1)
            output_dirpath_for_vdu = os.path.join(output_dirpath, vdu)
            os.mkdir(output_dirpath_for_vdu)
            with ta5g_admin_operations().connect_to_vdu_aic(host=host) as vdu_connection:
                try:
                    snapshot_status = vdu_connection.check_snapshot_status()
                    if snapshot_status =='idle':
                        vdu_connection.get_local_snapshot(directory=output_dirpath_for_vdu)
                    elif snapshot_status == 'local-ongoing':
                        snapshot_operation_info = vdu_connection.get_snapshot_operations_information()
                        operation_id = snapshot_operation_info[0]['operation_id']
                        vdu_connection.check_local_snapshot_status_and_save_it(directory=output_dirpath_for_vdu,
                                                                               operation_id=operation_id)
                    else:
                        snapshot_operation_info = vdu_connection.get_snapshot_operations_information()
                        operation_id = snapshot_operation_info[0]['operation_id']
                        vdu_connection.cancel_snapshot_operation(operation_id=operation_id)
                        vdu_connection.get_local_snapshot(directory=output_dirpath_for_vdu)
                except Exception as ex:
                    logger.console("Exception: {}".format(ex))
                    snapshot_status = vdu_connection.check_snapshot_status()
                    logger.console("Snapshot status is {}".format(snapshot_status))
                    raise ex

