    def collect_software_versions_aic(self, output_dirpath=None):
        """
        This method allows you to collect software versions (vcu, vdu, Wts) aic and create software_version.txt with the result
        :param string output_dirpath: Path to output directory
        """
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            vcu_version = vcu_connection.get_active_software_version()
        ap_version = (
            self.ta5g_iphy_instance.execute_wts_command(cmd="cd /ffs/run;ls TargetBD*.xml")
            .replace('TargetBD_', '')
            .replace('.xml', '')
        )
        try:
            wts_version = (subprocess.check_output('basename $(readlink /opt/wts/latest)', shell=True)).decode()
        except:
            wts_version = (subprocess.check_output('ls /opt/iphy | grep WTS', shell=True)).decode()
        vdu_version = self.get_vdu_sw_version_from_all_vdu()
        cmd = "echo 'vCU: {} \nvDU: {} \nAP: {} \nWTS: {}' > {}/software_version.txt".format(
            vcu_version, vdu_version, ap_version, wts_version, output_dirpath
        )
        subprocess.call(cmd, shell=True)


    def get_vdu_sw_version(self, host='192.168.255.129'):
        """
        This method allows you to collect software versions from given vdu aic and return the result
        :param string host: oam ip of vdu aic
        """
        with ta5g_admin_operations().connect_to_vdu_aic(host) as vdu_connection:
            vdu_state_data = vdu_connection.get_vdu_state_data()
            vdu_sw_version = vdu_state_data['software_version']
            return vdu_sw_version

    def get_vdu_sw_version_from_all_vdu(self):
        """
        This method allows you to collect software versions from all vdu's aic and return the result
        :param string host: oam ip of vdu aic
        """
        number_of_vdu = ta5g_admin_operations().get_number_of_vdu()
        dict_of_vdu_sw_version = {}
        for vdus in range(number_of_vdu):
            host = self.ta5g_iphy_instance.get_vdu_master_ip(vdu=vdus)
            sw_version = self.get_vdu_sw_version(host)
            dict_of_vdu_sw_version[host] = sw_version
        vdu_version_list = ["{}: {}".format(key, dict_of_vdu_sw_version[key]) for key in dict_of_vdu_sw_version]
        return vdu_version_list
